import { useEffect, useState } from "react";

export default function ReadingProgress() {
    const [progress, setProgress] = useState(0);
    useEffect(() => {
        const article = document.querySelector("[data-article-id]");
        if (!article)
            return;
        const update = () => {
            const rect = article.getBoundingClientRect();
            setProgress(Math.min(1, Math.max(0, -rect.top / Math.max(1, rect.height - window.innerHeight))));
        };
        update();
        window.addEventListener("scroll", update, { passive: true });
        return () => window.removeEventListener("scroll", update);
    }, []);
    return <div className="fixed top-0 left-0 z-(--z-overlay) h-1 bg-signal-500" style={{ width: `${progress * 100}%` }} aria-hidden="true" />;
}
